export { default as Kbd } from "./Kbd.vue";
export { default as KbdGroup } from "./KbdGroup.vue";
export type * from "./types.ts";

@layer components {
  /* Kbd: one key of a shortcut, a small muted box in the text font. */
  [data-slot="kbd"] {
    align-items: center;
    background: var(--vh-bg-muted);
    border: 0;
    border-radius: calc(var(--vh-radius) * 0.5);
    color: var(--vh-muted);
    display: inline-flex;
    font-family: inherit;
    font-size: 0.75rem;
    font-weight: 500;
    gap: 0.25rem;
    height: 1.25rem;
    justify-content: center;
    min-width: 1.25rem;
    padding: 0 0.25rem;
    pointer-events: none;
    user-select: none;
  }

  [data-slot="kbd"][data-size="sm"] {
    font-size: 0.6875rem;
    height: 1rem;
    min-width: 1rem;
  }

  [data-slot="kbd"] > svg {
    height: 0.75rem;
    width: 0.75rem;
  }

  [data-slot="kbd-group"] {
    align-items: center;
    border: 0;
    display: inline-flex;
    font: inherit;
    gap: 0.25rem;
    padding: 0;
  }
}

export type KbdSize = "sm" | "md";

export interface KbdProps {
  size?: KbdSize;
  label?: string;
}

export interface KbdSlots {
  default?: () => unknown;
}

export interface KbdGroupSlots {
  default?: () => unknown;
}
